def p(id,name,repo,layer,role,summary,needs,limit,platform='ROS 1',license='Check repository license',status='Research',evidence='Repository documentation',paper=None):
 url=repo if repo.startswith('http') else 'https://github.com/'+repo
 x=dict(id=id,name=name,repo=url,layer=layer,role=role,summary=summary,needs=needs,limit=limit,platform=platform,license=license,status=status,evidence=evidence,sources=[dict(label='Project repository / documentation',url=url)])
 if paper: x['sources'].append(dict(label='Paper',url=paper if paper.startswith('http') else 'https://arxiv.org/abs/'+paper))
 projects.append(x);return x
