# Enrich source evidence with inspected exact revisions and extracted paper links.
by={x['id']:x for x in projects}
for fn in ['clone-audit.json','tree-audit.json','clone-additional.json']:
 for item in json.loads((EV/fn).read_text()):
  repo,c=(item if isinstance(item,list) else (item['repo'],item.get('commit','')))
  for x in projects:
   if x['repo']=='https://github.com/'+repo and c:
    sha=c.split()[0]; x['commit']=sha;x['commitDate']=c.split()[1].split('T')[0]
    x['sources'].append(dict(label='Inspected source tree · '+sha[:8],url=x['repo']+'/tree/'+sha))
for x in projects:
 repo=x['repo'].replace('https://github.com/','')
 f=EV/'readmes'/(repo.replace('/','__')+'.txt')
 if f.exists():
  t=f.read_text(); papers=list(dict.fromkeys(re.findall(r'https?://arxiv.org/(?:abs|pdf)/\d{4}\.\d{4,5}',t)))
  if papers and not any(s['label']=='Paper' for s in x['sources']):x['sources'].append(dict(label='Paper linked by authors',url=papers[0].replace('/pdf/','/abs/')))
def src(id,label,url):by[id]['sources'].append(dict(label=label,url=url))
def pinned(id,path):return by[id]['repo']+'/blob/'+by[id].get('commit','HEAD')+'/'+path
src('cerlab','Nine constituent repositories',pinned('cerlab','.gitmodules'))
src('ntnu','Pinned workspace manifests',by['ntnu']['repo']+'/tree/'+by['ntnu']['commit']+'/repos')
