# Claim audit: atomic paraphrases, repeated assertions consolidated.
def c(id,topic,claim,verdict,finding,ids,urls=(),why=None):claims.append(dict(id=id,topic=topic,claim=claim,verdict=verdict,finding=finding,projects=ids,sources=[dict(label=l,url=u) for l,u in urls],why=why or ''))
c('C02','Commercial','Destination-driven autonomous flight and obstacle avoidance already exist commercially.','Supported with limits','Skydio is a valid commercial example in supported missions and conditions. This establishes the capability exists, not equivalence across all brands or environments.',['skydio'],[('Skydio X10',by['skydio']['repo']),('Safety guide',SKY)])
c('C03','Commercial','Skydio reliably avoids obstacles as small as a half-inch wire.','Overstated','The manufacturer safety guide warns against wires and branches smaller than 0.5 inch. A stated minimum-object limitation is not a guaranteed wire-detection specification.',['skydio'],[('Skydio safety guide',SKY)])
c('C04','Commercial','Skydio uses multiple cameras and real-time predictive autonomy.','Supported with limits','Multi-camera navigation is documented. Do not infer architecture details, performance guarantees or universal moving-obstacle avoidance from “predictive AI.”',['skydio'],[('X10 product documentation',by['skydio']['repo'])])
c('C05','Commercial','Pathfinder routes around terrain, buildings and geofences.','Supported with limits','Pathfinder uses geospatial information for route planning. Cached map routing cannot account for every new crane, wire or moving object; it complements onboard avoidance.',['skydio'],[('Pathfinder guide',PATH)])
c('C06','Commercial','Skydio can retain obstacle avoidance at night with NightSense.','Supported with limits','NightSense is dedicated illumination hardware for supported aircraft/configurations. Ordinary passive-camera performance at night is not the same capability.',['skydio'],[('X10 attachments',NIGHT)])
c('C07','Commercial','DJI waypoint + APAS actively bypasses obstacles rather than braking.','Contradicted','Mavic 4 Pro User Manual v1.2 §4.5 says waypoint flight brakes for obstacles whether Bypass or Brake is selected. APAS behavior is mode- and model-dependent.',['dji'],[('Mavic 4 Pro manual, p.36',DJI)],'This is a direct contradiction for the specific model Grok named.')
c('C08','Commercial','Mavic 4 Pro has omnidirectional vision plus LiDAR.','Supported with limits','Omnidirectional visual sensing and forward-facing LiDAR are documented. Do not describe it as omnidirectional LiDAR.',['dji'],[('Mavic 4 Pro manual',DJI)])
c('C09','Commercial','Docked/enterprise systems support remote mission execution.','Supported with limits','Commercial remote/docked operations exist. Remote operation, mission planning and sensed avoidance are separate capabilities with model-specific limits.',['skydio'],[('Pathfinder guide',PATH)])
c('C10','Commercial','Avoidance may fail with wires, transparent surfaces, weather or moving obstacles.','Supported','Manufacturer limitations support this caution. Grok’s broad reference to dynamic avoidance must be checked per model; Skydio’s guide describes static-obstacle avoidance.',['skydio','dji'],[('Skydio safety guide',SKY),('DJI manual',DJI)])
c('C11','Commercial','No continuous joystick input means no human oversight is needed.','Overstated','Autonomous execution does not establish unattended arbitrary-environment operation. Operator responsibilities and permitted operations are separate questions.',['skydio'],[('Skydio safety guide',SKY)])
c('C12','Commercial','BVLOS and related rules can still require pilots/observers.','Supported with limits','Directionally correct and jurisdiction-dependent. US Part 107 is one example with pilot/VLOS requirements and exceptions; this is not a statement of Jordanian or worldwide law. ',[],[('FAA Part 107 overview','https://www.faa.gov/newsroom/small-unmanned-aircraft-systems-uas-regulations-part-107')])
c('C13','Licensing','Skydio’s core autonomy is closed; SymForce is open.','Supported','Supporting open libraries and integration APIs are distinct from an open release of the commercial navigation stack.',['skydio','sym'],[('SymForce repository',by['sym']['repo']),('Skydio X10',by['skydio']['repo'])])
c('C14','Licensing','DJI is completely closed, with no source available.','Overstated','Core APAS/firmware algorithms are proprietary. DJI also publishes SDK source; “completely closed” is too broad when applied to its whole ecosystem.',['dji'],[('DJI Onboard SDK introduction','https://developer.dji.com/onboard-sdk/documentation/introduction/onboard-sdk-introduction.html')])
c('C15','Architecture','PX4 and ArduPilot are BSD/GPL open autopilots with missions and external control.','Supported','PX4 is BSD-3-Clause; ArduPilot GPL-3.0. Both supply control and mission foundations with different external-control and avoidance interfaces.',['px4','ardu'],[('PX4',by['px4']['repo']),('ArduPilot',by['ardu']['repo'])])
c('C16','Architecture','PX4 Avoidance is an official maintained planner to select today.','Outdated','The repository was archived in August 2024. The associated path-planning interface is unsupported and was removed in PX4 v1.15.',['oldavoid','px4'],[('Archived repository',by['oldavoid']['repo']),('PX4 removed interface',PXOLD)])
c('C17','Architecture','PX4 and ArduPilot offer only basic collision prevention beneath companion autonomy.','Incomplete','PX4 collision prevention and ArduPilot BendyRuler are materially different. ArduPilot can detour in AUTO/GUIDED/RTL; Dijkstra+BendyRuler combines fence routing and sensed-obstacle avoidance.',['px4','ardu'],[('PX4 collision prevention','https://docs.px4.io/v1.16/en/computer_vision/collision_prevention'),('BendyRuler',BEND),('Combined avoidance',DIJK)])
c('C18','Architecture','Fast-Planner and EGO-Planner can supply local obstacle-avoiding trajectories.','Supported','They are real planners with public code and flight research. They require map/sensor-state inputs and a controller; neither is an autopilot or turnkey full product.',['fast','ego','egoswarm'],[('Fast-Planner',by['fast']['repo']),('EGO-Planner',by['ego']['repo'])])
c('C19','Architecture','OctoMap/Voxblox, VIO and SLAM provide interchangeable perception blocks.','Incomplete','Occupancy/distance maps and pose estimators solve different problems. OpenVINS/VINS/ORB-SLAM3 do not automatically provide a dense collision map; wrappers, frames, timing and representations must agree.',['octo','voxblox','openvins','vins','orb'],[('Voxblox',by['voxblox']['repo']),('OpenVINS',by['openvins']['repo']),('ORB-SLAM3',by['orb']['repo'])])
c('C20','Architecture','ROS/ROS 2 plus MAVLink or DDS connects companion perception/planning to flight control.','Supported with limits','This is a common architecture. MAVROS bridges MAVLink; PX4’s ROS 2 interface uses its compatible DDS path. ROS versions and setpoint/state contracts are not automatically compatible.',['mavros','px4ros','fastdrone'],[('MAVROS',by['mavros']['repo']),('PX4 ROS 2 interface docs','https://docs.px4.io/main/en/ros2/px4_ros2_interface_lib')])
c('C21','Architecture','Jetson, Raspberry Pi or NUC can run companion autonomy.','Supported with limits','All are plausible compute classes; feasibility depends on sensing, model, rates and power. A Pi cannot be assumed to run every stack at target speed. Small PULP-Dronet shows Jetson is not universally mandatory.',['fastdrone','uniquad','pulp'],[('Fast-Drone reference',by['fastdrone']['repo']),('UniQuad',by['uniquad']['repo']),('PULP-Dronet',by['pulp']['repo'])])
c('C22','Architecture','PX4 is currently the most common foundation for this work.','Unsubstantiated','The reviewed examples make PX4 a reasonable and frequent choice. No defined population, survey or adoption measurement was supplied to justify the superlative.',['px4','ardu'],[('PX4 project',by['px4']['repo']),('ArduPilot project',by['ardu']['repo'])])
c('C23','Architecture','Almost always start by assembling disparate projects yourself.','Misleading emphasis','Many reusable integrated systems already perform substantial assembly. Choose between adopting a reference stack and composing components; integration effort remains in both.',['cerlab','mrs','fastdrone','ntnu','airstack'],[('CERLAB submodules',pinned('cerlab','.gitmodules')),('Fast-Drone-250',by['fastdrone']['repo']),('MRS',by['mrs']['repo'])])
c('C24','Architecture','Integration means drivers, map/trajectory interfaces, tuning and calibration—not random copying.','Supported','Correct. Concrete interface issues include frame conventions, sensor timestamps/extrinsics, odometry rates, map semantics and controller setpoints. Integrated releases reduce this work rather than eliminating it.',['gary','fastdrone'],[('Concrete integration modifications',by['gary']['repo']),('Reference assembly',by['fastdrone']['repo'])])
c('C25','Named systems','px4_fast_planner has already combined planner and autopilot components.','Supported with limits','Actual integration source exists, with Fast-Planner and MAVROS controller dependencies. The inspected head is from 2020; it should not be presented as a maintained modern full stack.',['px4fast'],[('Inspected integration repository',by['px4fast']['repo'])])
c('C26','Named systems','No-GPS Autonomous Drone System already wires everything together; launch files exist.','Contradicted','The inspected default branch contains only README.md and LICENSE. No implementation or launch files support this claim.',['nogps'],[('Inspected repository tree',by['nogps']['sources'][-1]['url'])])
c('C27','Named systems','CERLAB is a real integrated CMU autonomy system.','Supported with limits','Verified nine module repositories and real navigation/exploration examples. The perception-to-control description needs the qualification that a suitable pose/odometry source is an external input.',['cerlab'],[('CERLAB',by['cerlab']['repo']),('Module manifest',pinned('cerlab','.gitmodules')),('Mapping inputs',by['cermap']['repo'])])
c('C28','Named systems','NTNU Unified Autonomy Stack is an integrated open system.','Supported with limits','Real code, workspace manifests and a 2026 paper support the claim. It is a newer public wrapper, mixes ROS versions, and exposes alternative modules rather than one mandatory pipeline.',['ntnu'],[('NTNU repository',by['ntnu']['repo']),('Paper','https://arxiv.org/abs/2605.12735')])
c('C29','Named systems','OmniNxt provides integrated perception, planning and control.','Supported with limits','Paper and assembly guide support a real reference system. The tiny root repository points to external branch-specific implementations; it is not self-contained.',['omni'],[('OmniNxt guide',by['omni']['repo']),('Paper','https://arxiv.org/abs/2403.20085')])
c('C30','Named systems','Agilicious is a freely open-source full obstacle-avoidance stack.','Misleading','The framework is real, but current core access is governed by an academic agreement. Control/hardware framework and related obstacle-avoidance experiments are not the same release.',['agilicious','agile'],[('Current academic agreement','https://rpg.ifi.uzh.ch/docs/Agilicious_LICENSE_AGREEMENT_ACADEMIC_USE.pdf'),('Agilicious distribution',by['agilicious']['repo'])])
c('C31','Named systems','Aerostack2 supplies an end-to-end forest-avoidance system.','Overstated','A genuine ROS 2 autonomy framework. Inspected A* plugin uses a 2D occupancy map; general 3D avoidance needs a chosen perception/planning configuration.',['as2'],[('Path planning behavior source',by['as2']['repo']+'/tree/'+by['as2']['commit']+'/as2_behaviors/as2_behaviors_path_planning'),('Framework paper','https://arxiv.org/abs/2303.18237')])
c('C32','Named systems','MRS already integrates the pieces.','Supported with limits','A substantial deployed flight framework with optional estimation/mapping/planning modules. Current ROS 2 migration status matters; some ROS 1 modules are not yet ported.',['mrs'],[('Current branch modules and TODOs',by['mrs']['repo'])])
c('C33','Named systems','Altnautica adds the higher-level fly-here-and-avoid-stuff behavior.','Not established','Actual operational agent code exists. Vision navigation docs establish VIO/pose support, not a mature general 3D obstacle planner. Treat it as an operations platform, not a verified Skydio equivalent.',['alt'],[('Drone agent',by['alt']['repo']),('Vision navigation docs','https://docs.altnautica.com/drone-agent/vision-nav-getting-started'),('Extensions','https://docs.altnautica.com/drone-agent/extensions-catalog')])
c('C34','Capability','These public systems can fly real obstacle-avoiding missions.','Supported with limits','Multiple papers and releases support real flight in specific setups. A paper demonstration, released code, reproducible deployment and product robustness are four different evidence levels.',['cerlab','omni','super','agile'],[('OmniNxt paper','https://arxiv.org/abs/2403.20085'),('SUPER paper',by['super']['sources'][1]['url'])])
c('C35','Capability','None match Skydio in robustness, thin obstacles, night performance or polish.','Unsubstantiated','No matched public comparison across those dimensions was supplied. SUPER reports thin-wire and night experiments, but compares a DJI Mavic 3 in the wire test—not Skydio. There is no justified universal ranking.',['super','skydio'],[('SUPER paper',by['super']['sources'][1]['url']),('Skydio limitations',SKY)])
c('C37','Capability','Most complete stacks require matching reference sensors and calibration.','Supported with limits','Reference-stack documentation supports substantial hardware/configuration dependence. “Most” is qualitative here; no census was performed, and Jetson-class compute is not universal.',['omni','fastdrone','ntnu','pulp'],[('OmniNxt',by['omni']['repo']),('Fast-Drone-250',by['fastdrone']['repo']),('PULP-Dronet',by['pulp']['repo'])])
c('C38','Capability','Starting from an assembled stack leaves adaptation rather than inventing the architecture.','Supported','A fair practical conclusion. Choose a stack whose sensors, license, ROS branch and task match your project, then validate the resulting system in your actual environment.',['cerlab','mrs','fastdrone','ntnu'],[('CERLAB assembly',pinned('cerlab','.gitmodules')),('NTNU manifests',by['ntnu']['sources'][-1]['url'])])
